* { box-sizing: border-box; }
:root {
  --bg0: var(--fl-bg); --bg1: var(--fl-surface-2); --card: var(--fl-surface); --card2: var(--fl-surface-2);
  --line: var(--fl-border); --ink: var(--fl-text); --ink-dim: var(--fl-muted); --ink-faint: var(--fl-faint);
  --accent: var(--fl-accent); --accent2: color-mix(in srgb, var(--fl-accent) 72%, var(--fl-text) 28%); --green: var(--fl-good); --amber: var(--fl-warn); --red: var(--fl-bad);
}
body { margin: 0; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: var(--ink);
  background: radial-gradient(1200px 600px at 50% -10%, var(--bg1), var(--bg0)); min-height: 100vh; }
.wrap { max-width: 1180px; margin: 0 auto; padding: 26px 22px 56px; }

/* top bar */
.topbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-bottom: 22px; }
.brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
.logo { width: 46px; height: 46px; flex: none; border-radius: 13px; display: grid; place-items: center;
  font-size: 22px; font-weight: 800; color: var(--fl-accent-contrast); background: linear-gradient(135deg, var(--accent), var(--accent2)); }
.topbar h1 { margin: 0; font-size: 24px; letter-spacing: -0.01em; }
.sub { margin: 2px 0 0; color: var(--ink-dim); font-size: 13px; }
.who { display: flex; align-items: center; gap: 14px; }
.greet { color: var(--ink-dim); font-size: 13px; }
.btn { border: 1px solid var(--line); background: var(--card); color: var(--ink); font: inherit; font-size: 14px;
  font-weight: 600; padding: 9px 16px; border-radius: 11px; cursor: pointer; transition: all .14s ease; }
.btn:hover { border-color: color-mix(in srgb, var(--fl-accent) 45%, var(--fl-border)); }
.btn.primary { border: none; color: var(--fl-accent-contrast); background: linear-gradient(135deg, var(--accent), var(--accent2)); }
.btn.primary:hover { filter: brightness(1.08); }

/* stat cards */
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 18px; }
.stat { position: relative; background: var(--card); border: 1px solid var(--line); border-radius: 16px; padding: 16px 18px; overflow: hidden; }
.stat::before { content: ""; position: absolute; inset: 0 0 auto 0; height: 3px; background: linear-gradient(90deg, var(--accent), var(--accent2)); opacity: .8; }
.stat.win::before { background: linear-gradient(90deg, var(--green), color-mix(in srgb, var(--green) 68%, var(--fl-text) 32%)); }
.stat .k { color: var(--ink-dim); font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .05em; }
.stat .v { font-size: 30px; font-weight: 800; margin: 4px 0 2px; letter-spacing: -0.02em; }
.stat.win .v { color: var(--green); }
.stat .d { color: var(--ink-faint); font-size: 12px; }

/* layout */
.grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.panel { background: var(--card2); border: 1px solid var(--line); border-radius: 18px; padding: 18px 20px; }
.panel h2 { margin: 0 0 2px; font-size: 15px; display: flex; align-items: center; gap: 10px; }
.hint { margin: 0 0 14px; color: var(--ink-faint); font-size: 12px; }
.panel h2 .hint { margin: 0; font-weight: 500; padding: 2px 9px; border-radius: 999px; background: var(--fl-surface-2); }

/* category bars */
.bars { display: flex; flex-direction: column; gap: 14px; }
.bar-row { display: grid; grid-template-columns: 92px 1fr auto; align-items: center; gap: 12px; }
.bar-row .name { font-size: 13px; color: var(--ink-dim); }
.bar-track { height: 10px; background: var(--fl-track); border-radius: 999px; overflow: hidden; }
.bar-fill { height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), var(--accent2)); transition: width .5s ease; }
.bar-row .amt { text-align: right; font-weight: 700; font-size: 14px; white-space: nowrap; }
.bar-row .amt small { display: block; font-weight: 500; font-size: 11px; color: var(--ink-faint); }

/* pending list */
.list { display: flex; flex-direction: column; }
.item { display: flex; align-items: center; gap: 12px; padding: 11px 2px; border-bottom: 1px solid var(--fl-border); }
.item:last-child { border-bottom: none; }
.item .main { flex: 1; min-width: 0; }
.item .t { font-weight: 600; font-size: 14px; }
.item .m { color: var(--ink-faint); font-size: 12px; margin-top: 2px; }
.badge { flex: none; padding: 3px 10px; border-radius: 999px; font-size: 11px; font-weight: 700; text-transform: capitalize; }
.item .val { flex: none; font-weight: 700; font-size: 14px; min-width: 74px; text-align: right; }

/* quick actions */
.actions { display: flex; flex-wrap: wrap; gap: 12px; }
.action { flex: 1; min-width: 180px; text-align: left; display: grid; grid-template-columns: auto 1fr; grid-template-rows: auto auto;
  column-gap: 12px; row-gap: 2px; padding: 14px 16px; border: 1px solid var(--line); background: var(--card); border-radius: 14px;
  color: var(--ink); cursor: pointer; font: inherit; transition: all .14s ease; }
.action:hover { border-color: color-mix(in srgb, var(--fl-accent) 40%, var(--fl-border)); background: color-mix(in srgb, var(--fl-accent) 8%, var(--fl-surface)); }
.action .ico { grid-row: 1 / span 2; width: 38px; height: 38px; border-radius: 11px; display: grid; place-items: center;
  font-size: 18px; font-weight: 700; background: color-mix(in srgb, var(--fl-accent) 14%, transparent); color: var(--fl-accent); }
.action .lbl { font-weight: 600; font-size: 14px; align-self: end; }
.action .cap { color: var(--ink-faint); font-size: 12px; align-self: start; }

.footer { text-align: center; color: var(--ink-faint); font-size: 12px; margin-top: 26px; }
.empty { text-align: center; padding: 30px 16px; color: var(--ink-dim); }
.empty b { display: block; color: var(--ink); font-size: 15px; margin-bottom: 6px; }

@media (max-width: 900px) { .stats { grid-template-columns: repeat(2, 1fr); } .grid { grid-template-columns: 1fr; } }
@media (max-width: 480px) { .stats { grid-template-columns: 1fr; } }

// index.ts — entry point. Wires the DOM to the FormLogic app-scoped SDK.
import {
  Expense,
  StatusKey,
  StatusTotals,
  CategorySpend,
  RawRecord,
  toExpense,
  aggregate,
  categoryBreakdown,
  recentPending,
  formatCurrency,
} from "./data";

interface FieldMeta {
  id: string;
  label: string;
  type: string;
}
interface FormMeta {
  formId: string;
  displayName: string;
  fields: FieldMeta[];
}
interface AppContext {
  appName: string;
  appSlug: string;
  forms: FormMeta[];
}
interface CurrentUser {
  name?: string;
  email?: string;
}
interface FormLogicSDK {
  context(): Promise<AppContext>;
  submit(formId: string, answers: Record<string, unknown>): Promise<unknown>;
  records(formId: string, opts?: { limit?: number }): Promise<RawRecord[]>;
  currentUser(): Promise<CurrentUser | null>;
  navigate(formId: string): void;
  toast: { success(msg: string): void; error(msg: string): void };
  escapeHtml(value: unknown): string;
}

declare global {
  interface Window {
    FormLogic: FormLogicSDK;
  }
}

const FL = window.FormLogic;

const STATUS_BADGE: Record<StatusKey, { label: string; bg: string; fg: string }> = {
  pending: { label: "Pending", bg: "color-mix(in srgb, var(--fl-warn) 16%, transparent)", fg: "var(--fl-warn)" },
  approved: { label: "Approved", bg: "color-mix(in srgb, var(--fl-good) 16%, transparent)", fg: "var(--fl-good)" },
  rejected: { label: "Rejected", bg: "color-mix(in srgb, var(--fl-bad) 16%, transparent)", fg: "var(--fl-bad)" },
};

function findForm(ctx: AppContext, name: string): FormMeta | undefined {
  const target = name.trim().toLowerCase();
  return ctx.forms.find((f) => (f.displayName || "").trim().toLowerCase() === target);
}

function setHeader(appName: string, user: CurrentUser | null): void {
  const nameEl = document.getElementById("app-name");
  const userEl = document.getElementById("app-user");
  if (nameEl) nameEl.textContent = appName || "Expense Manager";
  if (userEl) {
    const who = user && (user.name || user.email) ? user.name || user.email : "";
    userEl.innerHTML = who
      ? "Signed in as <b>" + FL.escapeHtml(who) + "</b>"
      : "Expense approvals dashboard";
  }
}

function setBody(html: string): void {
  const body = document.getElementById("body");
  if (body) body.innerHTML = html;
}

function badge(status: StatusKey): string {
  const b = STATUS_BADGE[status];
  return (
    '<span class="badge" style="background:' +
    b.bg +
    ";color:" +
    b.fg +
    '">' +
    b.label +
    "</span>"
  );
}

function renderShell(): string {
  return (
    '<div class="wrap">' +
    '<header class="topbar"><div class="brand">' +
    '<div class="logo">&#8355;</div>' +
    '<div><h1 id="app-name">Expense Manager</h1>' +
    '<p class="sub">Submit, review &amp; approve team expenses</p></div>' +
    "</div>" +
    '<div class="who"><div class="greet" id="app-user">Loading&hellip;</div>' +
    '<button class="btn primary" id="top-new" type="button">+ New expense</button>' +
    "</div></header>" +
    '<main id="body"><div class="empty">Loading dashboard&hellip;</div></main>' +
    '<p class="footer">Powered by FormLogic &middot; live spend dashboard</p>' +
    "</div>"
  );
}

function renderError(msg: string): string {
  return '<div class="empty"><b>Something went wrong</b>' + FL.escapeHtml(msg) + "</div>";
}

function renderStats(
  totals: Record<StatusKey, StatusTotals>,
  allCount: number,
  allAmount: number
): string {
  const items = (n: number) => (n === 1 ? "1 item" : n + " items");
  const cards = [
    { cls: "", k: "Pending", v: totals.pending.amount, d: items(totals.pending.count) },
    { cls: "win", k: "Approved", v: totals.approved.amount, d: items(totals.approved.count) },
    { cls: "", k: "Rejected", v: totals.rejected.amount, d: items(totals.rejected.count) },
    { cls: "", k: "All expenses", v: allAmount, d: items(allCount) },
  ];
  const inner = cards
    .map(
      (c) =>
        '<div class="stat ' +
        c.cls +
        '"><div class="k">' +
        c.k +
        '</div><div class="v">' +
        formatCurrency(c.v) +
        '</div><div class="d">' +
        c.d +
        "</div></div>"
    )
    .join("");
  return '<div class="stats">' + inner + "</div>";
}

function renderCategories(cats: CategorySpend[]): string {
  let body: string;
  if (!cats.length) {
    body = '<div class="empty"><b>No spend yet</b>Approved and pending expenses will show here.</div>';
  } else {
    const max = Math.max.apply(null, cats.map((c) => c.amount).concat(1));
    const rows = cats
      .map((c) => {
        const pct = Math.max(4, Math.round((c.amount / max) * 100));
        const items = c.count === 1 ? "1 item" : c.count + " items";
        return (
          '<div class="bar-row"><span class="name">' +
          FL.escapeHtml(c.category) +
          '</span><div class="bar-track"><div class="bar-fill" data-pct="' +
          pct +
          '" style="width:0"></div></div>' +
          '<span class="amt">' +
          formatCurrency(c.amount) +
          "<small>" +
          items +
          "</small></span></div>"
        );
      })
      .join("");
    body = '<div class="bars">' + rows + "</div>";
  }
  return (
    '<section class="panel"><h2>Spend by category</h2>' +
    '<p class="hint">Approved and pending expenses, excludes rejected.</p>' +
    body +
    "</section>"
  );
}

function renderPending(pending: Expense[], pendingCount: number): string {
  const countTag =
    '<span class="hint" style="margin:0">' +
    (pendingCount === 1 ? "1 waiting" : pendingCount + " waiting") +
    "</span>";
  let body: string;
  if (!pending.length) {
    body = '<div class="empty"><b>All caught up</b>No expenses are waiting for approval.</div>';
  } else {
    const rows = pending
      .map((e) => {
        const desc = FL.escapeHtml(e.description || "Untitled expense");
        const metaBits = [FL.escapeHtml(e.category), FL.escapeHtml(e.submittedBy || "Unknown")];
        if (e.date) metaBits.push(FL.escapeHtml(e.date));
        return (
          '<div class="item"><div class="main"><div class="t">' +
          desc +
          '</div><div class="m">' +
          metaBits.join(" &middot; ") +
          "</div></div>" +
          badge(e.status) +
          '<span class="val">' +
          formatCurrency(e.amount) +
          "</span></div>"
        );
      })
      .join("");
    body = '<div class="list">' + rows + "</div>";
  }
  return (
    '<section class="panel"><h2>Pending approvals' + countTag + "</h2>" +
    '<p class="hint">Most recent submissions awaiting a decision.</p>' +
    body +
    "</section>"
  );
}

function renderActions(hasBudget: boolean): string {
  const budgetAction = hasBudget
    ? '<button class="action" type="button" data-action="budgets">' +
      '<span class="ico">&#36;</span><span class="lbl">Manage budgets</span>' +
      '<span class="cap">Set monthly category limits</span></button>'
    : "";
  return (
    '<section class="panel" style="margin-top:16px"><h2>Quick actions</h2>' +
    '<div class="actions">' +
    '<button class="action" type="button" data-action="new-expense">' +
    '<span class="ico">+</span><span class="lbl">New expense</span>' +
    '<span class="cap">Submit an expense for approval</span></button>' +
    budgetAction +
    '<button class="action" type="button" data-action="refresh">' +
    '<span class="ico">&#8635;</span><span class="lbl">Refresh</span>' +
    '<span class="cap">Reload the latest expenses</span></button>' +
    "</div></section>"
  );
}

function renderDashboard(expenses: Expense[], hasBudget: boolean): string {
  const totals = aggregate(expenses);
  const cats = categoryBreakdown(expenses);
  const pendingAll = expenses.filter((e) => e.status === "pending");
  const pending = recentPending(expenses);
  const allAmount = expenses.reduce((sum, e) => sum + e.amount, 0);
  return (
    renderStats(totals, expenses.length, allAmount) +
    '<div class="grid">' +
    renderCategories(cats) +
    renderPending(pending, pendingAll.length) +
    "</div>" +
    renderActions(hasBudget)
  );
}

function animateBars(): void {
  requestAnimationFrame(() => {
    const bars = document.querySelectorAll<HTMLElement>(".bar-fill");
    bars.forEach((el) => {
      el.style.width = (el.getAttribute("data-pct") || "0") + "%";
    });
  });
}

function wireBodyActions(expenseFormId: string, budgetFormId: string | null): void {
  const body = document.getElementById("body");
  if (!body) return;
  body.querySelectorAll("[data-action]").forEach((el) => {
    el.addEventListener("click", () => {
      const action = el.getAttribute("data-action");
      if (action === "new-expense") {
        FL.navigate(expenseFormId);
      } else if (action === "budgets" && budgetFormId) {
        FL.navigate(budgetFormId);
      } else if (action === "refresh") {
        void refresh(expenseFormId, budgetFormId);
      }
    });
  });
}

async function refresh(expenseFormId: string, budgetFormId: string | null): Promise<void> {
  let records: RawRecord[] = [];
  try {
    records = await FL.records(expenseFormId, { limit: 500 });
  } catch (err) {
    setBody(renderError("Could not load expenses. Please try again."));
    FL.toast.error("Failed to load expenses");
    return;
  }
  const expenses: Expense[] = records.map(toExpense);
  setBody(renderDashboard(expenses, budgetFormId !== null));
  wireBodyActions(expenseFormId, budgetFormId);
  animateBars();
}

async function main(): Promise<void> {
  const root = document.getElementById("app");
  if (!root) return;
  root.innerHTML = renderShell();

  let ctx: AppContext;
  try {
    ctx = await FL.context();
  } catch (err) {
    setBody(renderError("Could not connect to this app."));
    return;
  }

  const user = await FL.currentUser().catch(() => null);
  setHeader(ctx.appName, user);

  const expenseForm = findForm(ctx, "Expense");
  const budgetForm = findForm(ctx, "Category Budget");

  if (!expenseForm) {
    setBody(renderError("The 'Expense' form was not found in this app."));
    return;
  }

  const budgetId = budgetForm ? budgetForm.formId : null;

  const topNew = document.getElementById("top-new");
  if (topNew) {
    topNew.addEventListener("click", () => FL.navigate(expenseForm.formId));
  }

  await refresh(expenseForm.formId, budgetId);
}

main().catch(() => {
  const root = document.getElementById("app");
  if (root) {
    root.innerHTML =
      '<div class="wrap"><div class="empty"><b>Something went wrong</b>The dashboard could not be loaded.</div></div>';
  }
});

// data.ts — pure data helpers for the Expenses dashboard.
// Imported by index.ts with a relative path to prove multi-file bundling.

export type StatusKey = "pending" | "approved" | "rejected";

export interface RawRecord {
  id: string;
  answers: Record<string, unknown>;
  submittedAt: string;
}

export interface Expense {
  id: string;
  description: string;
  amount: number;
  category: string;
  status: StatusKey;
  submittedBy: string;
  date: string;
  submittedAt: string;
}

export interface StatusTotals {
  count: number;
  amount: number;
}

export interface CategorySpend {
  category: string;
  amount: number;
  count: number;
}

// Choice/text values can arrive in a few shapes; normalise defensively.
export function normalizeStatus(raw: unknown): StatusKey {
  const s = String(raw ?? "").toLowerCase();
  if (s.includes("approve")) return "approved";
  if (s.includes("reject")) return "rejected";
  return "pending";
}

export function toNumber(raw: unknown): number {
  if (typeof raw === "number") return Number.isFinite(raw) ? raw : 0;
  const n = parseFloat(String(raw ?? "").replace(/[^0-9.\-]/g, ""));
  return Number.isFinite(n) ? n : 0;
}

export function prettify(raw: unknown): string {
  const s = String(raw ?? "").trim();
  if (!s) return "Uncategorized";
  return s.replace(/[_\-]+/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

export function formatCurrency(n: number): string {
  return (
    "$" +
    (Math.round(n * 100) / 100).toLocaleString("en-US", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })
  );
}

export function toExpense(rec: RawRecord): Expense {
  const a = rec.answers || {};
  return {
    id: rec.id,
    description: String(a.description ?? ""),
    amount: toNumber(a.amount),
    category: prettify(a.category),
    status: normalizeStatus(a.status),
    submittedBy: String(a.submitted_by ?? ""),
    date: String(a.date ?? ""),
    submittedAt: rec.submittedAt,
  };
}

export function aggregate(expenses: Expense[]): Record<StatusKey, StatusTotals> {
  const base: Record<StatusKey, StatusTotals> = {
    pending: { count: 0, amount: 0 },
    approved: { count: 0, amount: 0 },
    rejected: { count: 0, amount: 0 },
  };
  for (const e of expenses) {
    base[e.status].count += 1;
    base[e.status].amount += e.amount;
  }
  return base;
}

// Spend excludes rejected expenses (money that will not be paid out).
export function categoryBreakdown(expenses: Expense[]): CategorySpend[] {
  const map = new Map<string, CategorySpend>();
  for (const e of expenses) {
    if (e.status === "rejected") continue;
    const cur = map.get(e.category) ?? { category: e.category, amount: 0, count: 0 };
    cur.amount += e.amount;
    cur.count += 1;
    map.set(e.category, cur);
  }
  return [...map.values()].sort((a, b) => b.amount - a.amount);
}

export function recentPending(expenses: Expense[], limit = 8): Expense[] {
  return expenses
    .filter((e) => e.status === "pending")
    .sort((a, b) => (b.submittedAt || "").localeCompare(a.submittedAt || ""))
    .slice(0, limit);
}
